#!/usr/bin/env python3
"""RSNA dense cache pilot (v4) -- Kaggle CPU script generated by scripts/make_kaggle_kernel.py.

Preprocessing measurement only: no training, no labels, no submission.
Builds the same 64 real training studies under each candidate cache policy,
validates the manifest, measures size/time/read cost, writes QC montages,
then deletes the image shards so the output stays small.
"""
from __future__ import annotations

import base64
import csv
import hashlib
import importlib
import importlib.metadata
import io
import json
import os
import shutil
import subprocess
import sys
import tarfile
import tempfile
import time
from pathlib import Path

SOURCE_B64 = ""  # filled by the generator
SOURCE_SHA256 = ""  # filled by the generator
BUILD_INFO = {}  # filled by the generator

N_PILOT = 64
PILOT_SEED = 2026
N_FULL_REQUESTED = 4219  # labeled + gold studies in the v3 campaign request list
QC_STUDIES = 3
CONFIGS = {
    "dense12-3slot": {"slots": "PILOT_SLOTS", "n_centers": 12, "center_lower": 0.05, "center_upper": 0.95},
    "dense12-5slot": {"slots": "STRUCTURAL_SLOTS", "n_centers": 12, "center_lower": 0.05, "center_upper": 0.95},
}
CODEC_PINS = {"pydicom": "3.0.1", "pylibjpeg": "2.1.0", "pylibjpeg-libjpeg": "2.4.0", "pylibjpeg-openjpeg": "2.6.0"}
WORK = Path(os.environ.get("RSNA_WORK_DIR", "/kaggle/working"))


def atomic_json(path: Path, value) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + ".tmp")
    tmp.write_text(json.dumps(value, indent=2, allow_nan=False), encoding="utf-8")
    tmp.replace(path)


def version(name):
    try:
        return importlib.metadata.version(name)
    except importlib.metadata.PackageNotFoundError:
        return None


def setup_packages() -> dict:
    target = Path(tempfile.gettempdir()) / "rsna-runtime-deps"
    pins = {"pydicom": CODEC_PINS["pydicom"]} if os.environ.get("RSNA_LOCAL_SMOKE") == "1" else CODEC_PINS
    needed = [f"{n}=={v}" for n, v in pins.items() if version(n) != v]
    if needed:
        target.mkdir(exist_ok=True)
        subprocess.run([sys.executable, "-m", "pip", "install", "--disable-pip-version-check", "--quiet",
                        "--no-deps", "--upgrade", "--target", str(target), *needed], check=True)
    sys.path.insert(0, str(target))
    importlib.invalidate_caches()
    import numpy as np
    import PIL
    import pydicom
    if pydicom.__version__ != CODEC_PINS["pydicom"]:
        raise RuntimeError("pydicom imported at an unexpected version; restart the session")
    if os.environ.get("RSNA_LOCAL_SMOKE") != "1":  # local smoke uses uncompressed synthetic DICOM
        for module in ("pylibjpeg", "libjpeg", "openjpeg"):
            importlib.import_module(module)
    return {"python": sys.version, "numpy": np.__version__, "Pillow": PIL.__version__,
            **{n: version(n) for n in CODEC_PINS}}


def unpack_source() -> Path:
    data = base64.b64decode(SOURCE_B64, validate=True)
    if hashlib.sha256(data).hexdigest() != SOURCE_SHA256:
        raise RuntimeError("Embedded source integrity failure")
    root = Path(tempfile.gettempdir()) / ("rsna-src-" + SOURCE_SHA256[:16])
    with tarfile.open(fileobj=io.BytesIO(data), mode="r:gz") as archive:
        for member in archive.getmembers():
            rel = Path(member.name)
            if not member.isfile() or rel.is_absolute() or ".." in rel.parts:
                raise RuntimeError("Invalid embedded archive member")
            out = root / rel
            out.parent.mkdir(parents=True, exist_ok=True)
            out.write_bytes(archive.extractfile(member).read())
    sys.path.insert(0, str(root / "src"))
    return root


def discover_root() -> Path:
    explicit = os.environ.get("RSNA_INPUT_ROOT")
    for candidate in ([Path(explicit)] if explicit else []) + [Path("/kaggle/input/rsna-knee-abnormality-detection"),
                                                               Path("/kaggle/input/competitions/rsna-knee-abnormality-detection")]:
        if (candidate / "train_series.csv").is_file() and (candidate / "train_series").is_dir():
            return candidate
    raise RuntimeError("Competition data not mounted")


def pilot_uids(series_csv: Path) -> list[str]:
    import numpy as np
    with series_csv.open(newline="") as handle:
        uids = sorted({row["StudyInstanceUID"] for row in csv.DictReader(handle)})
    order = np.random.default_rng(PILOT_SEED).permutation(len(uids))[:N_PILOT]
    return [uids[i] for i in order]


def quantiles(values) -> dict:
    import numpy as np
    arr = np.asarray(values, dtype=float)
    return {"mean": float(arr.mean()), "p50": float(np.percentile(arr, 50)),
            "p95": float(np.percentile(arr, 95)), "max": float(arr.max())}


def montage(volume, path: Path) -> None:
    """Slots x centers grid of the middle slice of each window (64 px tiles)."""
    import numpy as np
    from PIL import Image
    slots, centers = volume.shape[:2]
    tile = 64
    grid = np.zeros((slots * tile, centers * tile), dtype=np.uint8)
    for s in range(slots):
        for c in range(centers):
            image = Image.fromarray(np.ascontiguousarray(volume[s, c, 1])).resize((tile, tile))
            grid[s * tile:(s + 1) * tile, c * tile:(c + 1) * tile] = np.asarray(image)
    path.parent.mkdir(parents=True, exist_ok=True)
    Image.fromarray(grid).save(path)


def run_config(name: str, spec: dict, root: Path, uids: list[str]) -> dict:
    from rsna_knee.data import cache_build
    from rsna_knee.data.cache import read_shard
    dest = WORK / "pilot" / name / "cache"
    if dest.exists():
        shutil.rmtree(dest)
    started = time.perf_counter()
    manifest = cache_build.build_cache(
        series_csv=root / "train_series.csv", dicom_root=root / "train_series", dest=dest, study_ids=uids,
        size=224, n_centers=spec["n_centers"], center_lower=spec["center_lower"], center_upper=spec["center_upper"],
        slots=getattr(cache_build, spec["slots"]), strict_series=True, resume=False, progress_every=8)
    build_seconds = time.perf_counter() - started
    ready, reason = cache_build.manifest_ready(dest / "manifest.json")
    studies = manifest["studies"]
    sizes = [m["compressed_bytes"] for m in studies.values()]
    shape = manifest["preprocess_config"]
    raw_bytes = len(shape["slots"]) * shape["n_centers"] * 3 * shape["size"] ** 2
    read_times = []
    for i, uid in enumerate(studies):
        t0 = time.perf_counter()
        volume = read_shard(dest / f"{uid}.npz")
        read_times.append(time.perf_counter() - t0)
        if i < QC_STUDIES:
            montage(volume, WORK / "qc" / f"{name}-study{i}.png")
    n = max(len(studies), 1)
    per_study_bytes = sum(sizes) / n
    per_study_seconds = build_seconds / len(uids)
    result = {
        "config": name, "spec": spec, "manifest_ready": [ready, reason], "n_requested": len(uids),
        "n_built": len(studies), "n_quarantine": manifest["n_quarantine"],
        "quarantine_reasons": manifest["coverage"]["quarantine_reasons"],
        "preprocess_hash": manifest["preprocess_hash"], "manifest_sha256": manifest["manifest_sha256"],
        "build_seconds": round(build_seconds, 2), "seconds_per_study": round(per_study_seconds, 3),
        "compressed_bytes_per_study": quantiles(sizes) if sizes else None,
        "raw_bytes_per_study": raw_bytes, "compression_ratio": round(raw_bytes / per_study_bytes, 3) if sizes else None,
        "npz_read_seconds_per_study": quantiles(read_times) if read_times else None,
        "projected_full": {"n_studies": N_FULL_REQUESTED,
                           "compressed_gib": round(per_study_bytes * N_FULL_REQUESTED / 1024**3, 2),
                           "single_process_hours": round(per_study_seconds * N_FULL_REQUESTED / 3600, 2)},
        "coverage": manifest["coverage"],
        "note": "Projection from a 64-study random sample; not a guarantee for the full build.",
    }
    for path in list((WORK / "pilot" / name).rglob("*")):
        if path.suffix == ".npz" or (path.suffix == ".json" and path.name not in
                                     {"manifest.json", "coverage.json", "build-summary.json"}):
            path.unlink()
    print(json.dumps({"event": "config_done", **{k: result[k] for k in (
        "config", "manifest_ready", "n_built", "seconds_per_study", "compression_ratio", "projected_full")}}), flush=True)
    return result


def main() -> None:
    started = time.time()
    packages = setup_packages()
    unpack_source()
    root = discover_root()
    uids = pilot_uids(root / "train_series.csv")
    results = {}
    for name, spec in CONFIGS.items():
        results[name] = run_config(name, spec, root, uids)
        atomic_json(WORK / "pilot-result.json", {"status": "running", "results": results})
    atomic_json(WORK / "pilot-result.json", {
        "status": "ok", "scope": "preprocessing pilot only; no training, labels or submission",
        "source_sha256": SOURCE_SHA256, "build_info": BUILD_INFO, "packages": packages,
        "cpu_count": os.cpu_count(), "pilot_seed": PILOT_SEED,
        "pilot_uids_sha256": hashlib.sha256("\n".join(uids).encode()).hexdigest(),
        "wall_seconds": round(time.time() - started, 1), "results": results})
    print(json.dumps({"event": "pilot_complete", "wall_seconds": round(time.time() - started, 1)}), flush=True)


if __name__ == "__main__":
    main()
